#!/usr/bin/env node
/**
 * Builds the store upload artifacts.
 *
 * Three zips, because AMO needs a source archive as well: the extension ships
 * a WASM module generated by emscripten, and reviewers cannot read generated
 * code, so policy requires the sources and build instructions alongside it.
 */
import fs from 'node:fs/promises';
import path from 'node:path';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';
import { fileURLToPath } from 'node:url';
import { requireTools } from './lib/tools.mjs';

const run = promisify(execFile);

await requireTools('zip');
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const dist = path.join(root, 'dist');

const { name, version } = JSON.parse(
  await fs.readFile(path.join(root, 'extension/manifest.json'), 'utf8')
);
const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');

async function zip(file, cwd, args) {
  const out = path.join(dist, file);
  await fs.rm(out, { force: true });
  await run('zip', ['-r', '-q', '-X', out, ...args], { cwd });
  const { size } = await fs.stat(out);
  console.log(`${file}  ${(size / 1024).toFixed(0)} KB`);
}

for (const target of ['chrome', 'firefox']) {
  await zip(`${slug}-${target}-${version}.zip`, path.join(dist, target), ['.']);
}

// What a reviewer needs to rebuild dist/ from scratch, and nothing else.
await zip(`${slug}-source-${version}.zip`, root, [
  'extension',
  'scripts',
  'tests',
  'assets',
  'third_party',
  'package.json',
  'package-lock.json',
  'flake.nix',
  'flake.lock',
  'README.md',
  'PUBLISHING.md',
  '-x',
  'extension/icons/*', // regenerated by `npm run icons`
]);

console.log(`\nversion ${version} — see PUBLISHING.md for what to do with these`);
